"""Inspect verifier boundaries using generated bytes in /tmp only."""
import hashlib,json,tempfile,warnings,zipfile
from datetime import datetime,UTC
from pathlib import Path
from uuid import uuid4
from cygnusx.application.schemas.report_delivery import EvidenceManifest,DeliveryFile
from cygnusx.application.services.research_delivery_service import ResearchDeliveryBuilder
content=b'audit-only'
m=EvidenceManifest(package_id=uuid4(),task_id=uuid4(),snapshot_id=uuid4(),snapshot_digest='a'*64,package_version='audit',renderer_version='not_used',template_version='audit',files=(DeliveryFile(logical_name='result.txt',file_type='txt',size=len(content),sha256=hashlib.sha256(content).hexdigest(),source_object='audit',availability='available',integrity='verified',generation='generated'),),evidence_status='complete',validation_status='validated',generated_at=datetime.now(UTC))
out={}
with tempfile.TemporaryDirectory(prefix='cygnusx-audit-',dir='/tmp') as td:
 for mode in ['normal','extra_unlisted_file','duplicate_member','listed_file_tampered','path_traversal']:
  p=Path(td)/f'{mode}.zip'
  with warnings.catch_warnings():
   warnings.simplefilter('ignore',UserWarning)
   with zipfile.ZipFile(p,'w') as z:
    z.writestr('EvidenceManifest.json',m.model_dump_json())
    z.writestr('result.txt',b'changed' if mode=='listed_file_tampered' else content)
    if mode=='extra_unlisted_file':z.writestr('unlisted.txt',b'audit-extra')
    if mode=='duplicate_member':z.writestr('result.txt',content)
    if mode=='path_traversal':z.writestr('../escape.txt',b'not-extracted')
  try:
   ResearchDeliveryBuilder.verify_package(p)
   out[mode]='ACCEPTED_BY_VERIFIER'
  except ValueError:out[mode]='REJECTED_BY_VERIFIER'
assert out['listed_file_tampered']=='REJECTED_BY_VERIFIER'
assert out['path_traversal']=='REJECTED_BY_VERIFIER'
print(json.dumps({'scope':'offline verifier boundary, not an upload endpoint or runtime exploit','cases':out},indent=2))
